<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$sql='SELECT u.id,u.full_name,u.email,u.profile_picture, m.body AS last_body,m.created_at AS last_at FROM users u LEFT JOIN messages m ON m.id=(SELECT MAX(m2.id) FROM messages m2 WHERE (m2.sender_id=u.id AND m2.receiver_id=?) OR (m2.sender_id=? AND m2.receiver_id=u.id)) WHERE u.id<>? ORDER BY m.created_at DESC,u.full_name';$s=$pdo->prepare($sql);$s->execute([$_SESSION['user_id'],$_SESSION['user_id'],$_SESSION['user_id']]);$people=$s->fetchAll();$page_title='Messages';require __DIR__.'/includes/header.php'; ?><section class="panel"><div class="section-heading"><div><h1>Messages</h1><p class="muted">Choose a member to open your private conversation.</p></div><a class="button" href="search.php">Find people</a></div><?php if(!$people): ?><p>No other members are registered yet.</p><?php endif; ?><?php foreach($people as $p): ?><a class="conversation-row" href="conversation.php?user_id=<?= (int)$p['id'] ?>"><img src="<?= avatar($p) ?>" alt=""><div class="conversation-info"><strong><?= e($p['full_name']) ?></strong><p><?= e($p['last_body']??$p['email']) ?></p></div><?php if($p['last_at']): ?><small><?= e(date('d M · H:i',strtotime($p['last_at']))) ?></small><?php endif; ?></a><?php endforeach; ?></section><?php require __DIR__.'/includes/footer.php'; ?>